from fai.contracts import Read
from fai.logic import add_flankers_to_reads, calculate_delta, get_flankers


def test_add_flankers_to_read():
    reads = [
        Read("gene1", 5, 30),
        Read("gene2", 10, 33),
        Read("gene3", 15, 28),
    ]
    fasta_dict = {
        "gene1": "CCTCAGCCTCACCCTTACTCCTTGCCCCAGTTCATCGCCCCCGATGGGTCTAGTCACCAATCAGCCACGCGTCAGGTCAT",  # noqa: E501
        "gene2": "GCTCACTCATACTACACGAAGCAGTCGGCCGAATCCTCCGCACCCTGGGGGTCTCTCAACTCCGTGTGAAAAGTTCCTAT",  # noqa: E501
        "gene3": "CACCGCTTCCCCCTGCGAGCGGTGTCGCCAGGTTGAGCGTATGATGTCAGGTCTTTCAATATCATCCTGGAATGTATATT",  # noqa: E501
    }
    reads_with_flankers = add_flankers_to_reads(reads, fasta_dict)

    expected_flankers = {
        "gene1": ["T", "C", "A", "G", "C", "A", "T", "C"],
        "gene2": ["C", "A", "T", "A", "C", "A", "C", "C"],
        "gene3": ["C", "T", "G", "C", "A", "T", "G", "A"],
    }

    for read in reads_with_flankers:
        flankers = expected_flankers[read.gene_id]
        assert read.flankers == flankers


def test_add_flankers_to_read_with_invalid_gene():
    reads = [Read("gene1", 5, 30)]
    fasta_dict = {
        "gene2": "GCTCACTCATACTACACGAAGCAGTCGGCCGAATCCTCCGCACCCTGGGGGTCTCTCAACTCCGTGTGAAAAGTTCCTAT",  # noqa: E501
    }

    try:
        add_flankers_to_reads(reads, fasta_dict)
    except ValueError as e:
        assert (
            str(e) == "One or more gene IDs in reads do not match any key in gene_dict."
        )
    else:
        assert False, "Expected ValueError was not raised."


def test_get_flankers():
    gene1 = "CCTCAGCCTCACCCTTACTCCTTGCCCCAGTTCATCGCCCCCGATGGGTCTAGTCACCAATCAGCCACGCGTCAGGTCAT"  # noqa: E501
    flankers1 = ["T", "C", "A", "G", "C", "A", "T", "C"]
    assert flankers1 == get_flankers(5, 30, gene1)

    gene2 = "GCTCACTCATACTACACGAAGCAGTCGGCCGAATCCTCCGCACCCTGGGGGTCTCTCAACTCCGTGTGAAAAGTTCCTAT"  # noqa: E501
    flankers2 = ["C", "A", "T", "A", "C", "A", "C", "C"]
    assert flankers2 == get_flankers(10, 33, gene2)

    gene3 = "CACCGCTTCCCCCTGCGAGCGGTGTCGCCAGGTTGAGCGTATGATGTCAGGTCTTTCAATATCATCCTGGAATGTATATT"  # noqa: E501
    flankers3 = ["C", "T", "G", "C", "A", "T", "G", "A"]
    assert flankers3 == get_flankers(15, 28, gene3)


def test_get_flankers_gene_overflow():
    gene = "CCTCAGCCTCACCCTTACTCCTTGCCCCAGTTCATCGCCCCCGATGGGTCTAGTCACCAATCAGCCACGCGTCAGGTCAT"  # noqa: E501
    try:
        get_flankers(5, 100, gene)
    except ValueError as e:
        assert (
            str(e)
            == "Gene sequence is shorter than the specified gene position and size."
        )
    else:
        assert False, "Expected ValueError was not raised."


def test_calculate_delta():
    fasta_dict = {
        "gene1": "",  # noqa: E501
        "gene2": "",  # noqa: E501
        "gene3": "",  # noqa: E501
    }

    start_codon_index = 20
    read_size = 30
    reads_spacing = 3

    expected_delta = 15

    reads = [
        Read(
            gene, start_codon_index - expected_delta + offset * reads_spacing, read_size
        )
        for gene in fasta_dict
        for offset in range(
            0,
            (len(fasta_dict[gene]) - read_size - (start_codon_index - expected_delta))
            // reads_spacing
            + 1,
        )
    ]

    delta = calculate_delta(reads)

    assert delta == expected_delta

    expected_delta = 14

    reads = [
        Read(
            gene, start_codon_index - expected_delta + offset * reads_spacing, read_size
        )
        for gene in fasta_dict
        for offset in range(
            0,
            (len(fasta_dict[gene]) - read_size - (start_codon_index - expected_delta))
            // reads_spacing
            + 1,
        )
    ]

    assert delta == expected_delta

    expected_delta = 16

    reads = [
        Read(
            gene, start_codon_index - expected_delta + offset * reads_spacing, read_size
        )
        for gene in fasta_dict
        for offset in range(
            0,
            (len(fasta_dict[gene]) - read_size - (start_codon_index - expected_delta))
            // reads_spacing
            + 1,
        )
    ]

    assert delta == expected_delta
